        "answer": 0.333,
        "unit": "",
        "tolerance": 0.01,
        "hint": "Διαιρέστε τα δόντια $z_1$ δια $z_2$.",
        "explain": "Είναι $i_1 = \\frac{15}{45} = \\frac{1}{3} \\approx 0{,}333$."
